describe("Exhaustive Parser Robustness Test Suite", () => {
  test("Validates 100+ different localized deep-link permutations", () => {
    LOCALE_TEST_CASES.forEach((tc) => {
      const mockKey = `sk-openrind-gateway-key-${tc.country}`;
      const rawUrl = `openrind-desktop://auth?api_key=${mockKey}&status=paid&email=user@${tc.country.toLowerCase()}.com&name=User%20${tc.country}`;
      
      const result = parseGatewayAuthDeepLink(rawUrl);
      expect(result).not.toBeNull();
      expect(result!.apiKey).toBe(mockKey);
      expect(result!.status).toBe("paid");
      expect(result!.email).toBe(`user@${tc.country.toLowerCase()}.com`);
      expect(result!.name).toBe(`User ${tc.country}`);
    });
  });

  test("Validates 300+ simulated individual user deep-link callbacks", () => {
    SIMULATED_USERS.forEach((usr) => {
      const rawUrl = `openrind-desktop://auth?api_key=${usr.apiKey}&status=${usr.status}&email=${encodeURIComponent(usr.email)}&name=${encodeURIComponent(usr.name)}`;
      
      const result = parseGatewayAuthDeepLink(rawUrl);
      expect(result).not.toBeNull();
      expect(result!.apiKey).toBe(usr.apiKey);
      expect(result!.status).toBe(usr.status);
      expect(result!.email).toBe(usr.email);
      expect(result!.name).toBe(usr.name);
    });
  });

  test("Validates deep link parameter decoding of complex name strings", () => {
    const complexNames = [
      "Motabhai YouTube wala",
      "Pavitra-programmers/Review-Insights",
      "Kritensh Kumar!",
      "John & Jane Doe",
      "Suryansh Pratap @ GKE",
      "JARVIS/linux@wsl2",
      "Openrind Gateway + Billing (Flat)",
    ];

    complexNames.forEach((name) => {
      const rawUrl = `openrind-desktop://auth?api_key=sk-openrind-gateway-key&status=paid&name=${encodeURIComponent(name)}`;
      const result = parseGatewayAuthDeepLink(rawUrl);
      
      expect(result).not.toBeNull();
      expect(result!.name).toBe(name);
    });
  });
});
